input.content:
const http = require('http');
const fs = require('fs');

const envContent = fs.readFileSync('.env.test', 'utf8');

// Parse environment variables (simple parser)
const envVars = {};
envContent.split('\n').forEach(line => {
  const trimmed = line.trim();
  if (trimmed && !trimmed.startsWith('#') && trimmed.includes('=')) {
    const [key, ...valueParts] = trimmed.split('=');
    envVars[key.trim()] = valueParts.join('=');
  }
});

console.log('=== Environment Variables from .env.test ===');
console.log(JSON.stringify(envVars, null, 2));

console.log('\nSending to http://localhost:3003/api/doc-export...');

const postData = JSON.stringify(envVars);

const options = {
  hostname: 'localhost',
  port: 3003,
  path: '/api/doc-export',
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(postData)
  }
};

const req = http.request(options, (res) => {
  console.log(`Status Code: ${res.statusCode}`);

  let data = '';
  res.on('data', (chunk) => {
    data += chunk;
  });

  res.on('end', () => {
    if (res.statusCode === 200) {
      console.log('\nResponse:', data);
    } else {
      console.log('\nResponse:', data);
    }
  });
});

req.on('error', (error) => {
  console.error('Error:', error.message);
});

req.write(postData);
req.end();

